// Tool list for the app shell. Metadata comes from meta.json (generated by scripts/gen-tool-meta.mjs);
// each tool's implementation module is imported on first use, so its libraries load only when needed.
import type { Tool } from '../types';
import META from './meta.json';

export type ToolMeta = Omit<Tool, 'render'> & { module: string };

export const TOOL_META = META as ToolMeta[];

const modules = import.meta.glob<Record<string, unknown>>(['./*.ts', '!./index.ts', '!./lazy.ts']);

export async function loadTool(meta: ToolMeta): Promise<Tool> {
  const load = modules[`./${meta.module}.ts`];
  if (!load) throw new Error(`도구 모듈을 찾을 수 없습니다: ${meta.module}`);
  const mod = await load();
  for (const value of Object.values(mod)) {
    if (!Array.isArray(value)) continue;
    const tool = (value as Tool[]).find((t) => t?.id === meta.id);
    if (tool) return tool;
  }
  throw new Error(`도구를 찾을 수 없습니다: ${meta.id}`);
}
